@GameTestHolder("jdte") @PrefixGameTestTemplate(false)
public final class ChargedLightningRodGameTests {
 private static final BlockPos P=new BlockPos(2,1,2);
 private static ChargedLightningRodBE place(GameTestHelper h){for(var old:bolts(h))old.discard();h.setBlock(P.above(),Blocks.AIR);h.setBlock(P,JDTEBlocks.CHARGED_LIGHTNING_ROD.get());return (ChargedLightningRodBE)h.getBlockEntity(P);}
 private static void card(ChargedLightningRodBE b,Item i,int slot){if(!UpgradeHelper.getUpgradeHandler(b).insertItem(slot,new ItemStack(i),false).isEmpty())throw new IllegalStateException("card rejected");}
 private static List<net.minecraft.world.entity.LightningBolt> bolts(GameTestHelper h){return h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.LightningBolt.class,new AABB(h.absolutePos(P)).inflate(1,4,1),e->e.getPersistentData().contains(ChargedLightningRodBE.MACHINE_POSITION_TAG)&&e.getPersistentData().getLong(ChargedLightningRodBE.MACHINE_POSITION_TAG)==h.absolutePos(P).asLong());}
 private static void clear(GameTestHelper h){bolts(h).forEach(Entity::discard);h.setBlock(P,Blocks.AIR);}
 @GameTest(template="mineral_empty") public static void realWeatherGateAndSingleRestrictedCard(GameTestHelper h){var b=place(h);var level=h.getLevel();float rain=level.getRainLevel(1),thunder=level.getThunderLevel(1);try{level.setRainLevel(0);level.setThunderLevel(0);b.getEnergyStorage().setEnergy(10000);b.tickServer();h.assertTrue(bolts(h).isEmpty()&&b.getEnergyStorage().getEnergyStored()==10000,"clear weather does not spend or spawn");level.setRainLevel(1);level.setThunderLevel(0);h.assertTrue(!b.canOperateInWeather(),"ordinary rain insufficient");level.setThunderLevel(1);h.assertTrue(b.canOperateInWeather(),"real level rain+thunder flags permit source behavior");level.setRainLevel(0);level.setThunderLevel(0);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);h.assertTrue(b.canOperateInWeather()&&!UpgradeHelper.getUpgradeHandler(b).isItemValid(1,new ItemStack(JDTEItems.THUNDERSTORM_UPGRADE.get())),"one card bypasses weather");h.assertTrue(!UpgradeHelper.isUpgradeCompatible(new BasicTimeAcceleratorBE(h.absolutePos(P),JDTEBlocks.BASIC_TIME_ACCELERATOR.get().defaultBlockState()),UpgradeType.THUNDERSTORM),"card is rod-only");}finally{level.setRainLevel(rain);level.setThunderLevel(thunder);clear(h);}h.succeed();}
 @GameTest(template="mineral_empty") public static void realThunderstormProducesCompleteTaggedBolt(GameTestHelper h){var b=place(h);var l=h.getLevel();float r=l.getRainLevel(1),t=l.getThunderLevel(1);try{l.setRainLevel(1);l.setThunderLevel(1);b.getEnergyStorage().setEnergy(10000);b.tickServer();h.assertTrue(bolts(h).size()==1&&b.getEnergyStorage().getEnergyStored()==0&&b.getStrikeCooldown()==200,"one actual lightning at exact base cost/cooldown under level storm");var e=bolts(h).get(0);h.assertTrue(e.getPersistentData().getBoolean(ChargedLightningRodBE.NATURAL_LIGHTNING_TAG)&&e.getCause()==null&&e.level()==l,"source AE2LT natural-weather marker and no command/player cause");h.assertTrue(l.getBlockState(b.getBlockPos().above()).is(Blocks.LIGHTNING_ROD)&&b.ownsRod(),"real owned rod placed");b.tickServer();h.assertTrue(bolts(h).size()==1&&b.getStrikeCooldown()==200,"same-time invocation cannot duplicate strike/decrement cooldown");}finally{l.setRainLevel(r);l.setThunderLevel(t);clear(h);}h.succeed();}
 @GameTest(template="mineral_empty") public static void exactOverclockAndUltimateBatches(GameTestHelper h){var b=place(h);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);card(b,JDTEItems.OVERCLOCK_UPGRADE.get(),1);h.assertTrue(!UpgradeHelper.getUpgradeHandler(b).isItemValid(2,new ItemStack(JDTEItems.ULTIMATE_OVERCLOCK_UPGRADE.get()))&&!UpgradeHelper.usesLockedDelay(b),"speed cards exclusive and no generic speed multiplier");b.getEnergyStorage().setEnergy(200000);b.tickServer();h.assertTrue(bolts(h).size()==5&&b.getEnergyStorage().getEnergyStored()==0,"exact five40k strokes");clear(h);b=place(h);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);card(b,JDTEItems.ULTIMATE_OVERCLOCK_UPGRADE.get(),1);b.getEnergyStorage().setEnergy(5000000);b.tickServer();b.tickServer();h.assertTrue(bolts(h).size()==50&&b.getEnergyStorage().getEnergyStored()==0,"exact fifty100k strokes once per real time");clear(h);h.succeed();}
 @GameTest(template="mineral_empty") public static void insufficientAndPartialBudgetNeverChargeFailedStroke(GameTestHelper h){var b=place(h);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);card(b,JDTEItems.OVERCLOCK_UPGRADE.get(),1);b.getEnergyStorage().setEnergy(119999);b.tickServer();h.assertTrue(bolts(h).size()==2&&b.getEnergyStorage().getEnergyStored()==39999,"two complete strikes, remainder retained");clear(h);b=place(h);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);b.getEnergyStorage().setEnergy(9999);b.tickServer();h.assertTrue(bolts(h).isEmpty()&&b.getEnergyStorage().getEnergyStored()==9999&&h.getBlockState(P.above()).isAir(),"cannot fund even rod setup or strike");clear(h);h.succeed();}
 @GameTest(template="mineral_empty") public static void blockedRodAndTopBuildLimitNeverSpend(GameTestHelper h){var b=place(h);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);h.setBlock(P.above(),Blocks.STONE);b.getEnergyStorage().setEnergy(20000);b.tickServer();h.assertTrue(bolts(h).isEmpty()&&b.getEnergyStorage().getEnergyStored()==20000&&h.getBlockState(P.above()).is(Blocks.STONE),"does not replace blocked top");clear(h);h.succeed();}
 @GameTest(template="mineral_empty") public static void canceledJoinAndResourceMutationDiscardUnpaidLightning(GameTestHelper h){var b=place(h);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);b.getEnergyStorage().setEnergy(20000);java.util.function.Consumer<EntityJoinLevelEvent> cancel=e->{if(e.getEntity() instanceof net.minecraft.world.entity.LightningBolt lightning&&lightning.getPersistentData().getLong(ChargedLightningRodBE.MACHINE_POSITION_TAG)==h.absolutePos(P).asLong())e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(EventPriority.NORMAL,false,EntityJoinLevelEvent.class,cancel);try{b.tickServer();h.assertTrue(bolts(h).isEmpty()&&b.getEnergyStorage().getEnergyStored()==20000&&b.getStrikeCooldown()==0,"real Forge veto no debit/cooldown");}finally{MinecraftForge.EVENT_BUS.unregister(cancel);}clear(h);var other=place(h);card(other,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);other.getEnergyStorage().setEnergy(20000);java.util.function.Consumer<EntityJoinLevelEvent> mutate=e->{if(e.getEntity() instanceof net.minecraft.world.entity.LightningBolt lightning&&lightning.getPersistentData().getLong(ChargedLightningRodBE.MACHINE_POSITION_TAG)==h.absolutePos(P).asLong())other.getEnergyStorage().extractEnergy(7,false);};MinecraftForge.EVENT_BUS.addListener(EventPriority.NORMAL,false,EntityJoinLevelEvent.class,mutate);try{other.tickServer();h.assertTrue(bolts(h).isEmpty()&&other.getEnergyStorage().getEnergyStored()==19993,"callback sevenFE retained, no free/unpaid bolt");}finally{MinecraftForge.EVENT_BUS.unregister(mutate);}clear(h);h.succeed();}
 @GameTest(template="mineral_empty") public static void renderAndSoundIndependentAndSaved(GameTestHelper h){var b=place(h);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);b.setLightningEffects(false,true);b.getEnergyStorage().setEnergy(20000);b.tickServer();var e=bolts(h).get(0);h.assertTrue(!((MachineLightningEffects)e).jdte$isLightningRenderEnabled()&&!e.shouldRenderAtSqrDistance(1)&&!e.isSilent()&&!e.isRemoved(),"hidden actual entity still alive and audible");b.setLightningEffects(true,false);h.assertTrue(((MachineLightningEffects)e).jdte$isLightningRenderEnabled()&&e.isSilent(),"active bolt control updates independent flags");var tag=b.saveWithFullMetadata();var restored=(ChargedLightningRodBE)BlockEntity.loadStatic(b.getBlockPos(),b.getBlockState(),tag);h.assertTrue(restored.isLightningRenderEnabled()&&!restored.isLightningSoundEnabled()&&restored.getEnergyStorage().getEnergyStored()==10000&&restored.getStrikeCooldown()==200,"all source fields saved");clear(h);h.succeed();}
 @GameTest(template="mineral_empty",timeoutTicks=30) public static void hiddenSilentBoltRetainsVanillaRodAndPigEffects(GameTestHelper h){var b=place(h);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);b.setLightningEffects(false,false);b.getEnergyStorage().setEnergy(10000);var pig=h.spawn(EntityType.PIG,P.above(2));pig.setNoAi(true);b.tickServer();h.runAfterDelay(4,()->{h.assertTrue(h.getBlockState(P.above()).getValue(LightningRodBlock.POWERED),"actual vanilla onLightningStrike rod power");h.assertTrue(pig.isRemoved()&&!h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.monster.ZombifiedPiglin.class,new AABB(b.getBlockPos()).inflate(4)).isEmpty(),"non-visual-only natural lightning transforms a real pig while hidden/silent");for(var z:h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.monster.ZombifiedPiglin.class,new AABB(b.getBlockPos()).inflate(4)))z.discard();h.assertTrue(b.getEnergyStorage().getEnergyStored()==0,"vanilla effects do not re-debit");clear(h);h.succeed();});}
 @GameTest(template="mineral_empty") public static void livePortsCapacityAndRetainedInterfaces(GameTestHelper h){var b=place(h);var port=b.getCapability(ForgeCapabilities.ENERGY,Direction.NORTH).orElseThrow(IllegalStateException::new);h.assertTrue(port.receiveEnergy(Integer.MAX_VALUE,false)==10000000&&port.receiveEnergy(1,false)==0&&port.receiveEnergy(-1,false)==0,"bounded real FE capability");card(b,JDTEItems.CAPACITY_UPGRADE.get(),0);port.receiveEnergy(5000000,false);h.assertTrue(UpgradeHelper.getUpgradeHandler(b).extractItem(0,1,false).isEmpty()&&b.getEnergyStorage().getEnergyStored()==15000000,"capacity removal cannot discard storedFE");b.onChunkUnloaded();h.assertTrue(port.receiveEnergy(1,false)==0&&port.extractEnergy(1,false)==0,"unloaded capability inert");b.invalidateCaps();b.reviveCaps();b.onLoad();h.assertTrue(port.extractEnergy(1,false)==0&&b.getCapability(ForgeCapabilities.ENERGY).orElseThrow(IllegalStateException::new).getEnergyStored()==15000000,"old generation stays inert after revival");clear(h);h.succeed();}
 @GameTest(template="mineral_empty") public static void settingsCodecCopiesOnlyPresentationAndStaleMenuCannotToggle(GameTestHelper h){var b=place(h);b.setLightningEffects(false,false);b.getEnergyStorage().setEnergy(12345);var type=net.minecraft.core.registries.BuiltInRegistries.BLOCK_ENTITY_TYPE.getKey(b.getType());var codec=com.jdte.common.items.machinesettings.MachineSettingsCodecRegistry.find(type,b).orElseThrow();var encoded=codec.encode(b,h.getLevel().registryAccess());clear(h);var target=place(h);target.getEnergyStorage().setEnergy(777);codec.decode(encoded,h.getLevel().registryAccess()).orElseThrow().apply(target);h.assertTrue(!target.isLightningRenderEnabled()&&!target.isLightningSoundEnabled()&&target.getEnergyStorage().getEnergyStored()==777&&target.getStrikeCooldown()==0,"copy controls not resources/work/ownership");var player=h.makeMockSurvivalPlayer();player.setPos(Vec3.atCenterOf(target.getBlockPos().south()));var menu=new com.jdte.common.containers.ChargedLightningRodContainer(1,player.getInventory(),target.getBlockPos());h.assertTrue(menu.clickMenuButton(player,0)&&target.isLightningRenderEnabled()&&!menu.clickMenuButton(player,2),"real menu button allowlist");h.getLevel().removeBlockEntity(target.getBlockPos());h.assertTrue(!menu.clickMenuButton(player,0)&&target.isLightningRenderEnabled(),"stale menu cannot mutate removed owner");target.reviveCaps();target.clearRemoved();h.getLevel().setBlockEntity(target);clear(h);h.succeed();}
 @GameTest(template="mineral_empty") public static void realWrenchRelocationKeepsStateAndNoExtraRodItem(GameTestHelper h){var b=place(h);var actor=h.makeMockSurvivalPlayer();b.setPlacedBy(actor.getUUID());card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);b.setLightningEffects(false,false);b.getEnergyStorage().setEnergy(20000);b.tickServer();bolts(h).forEach(Entity::discard);h.assertTrue(b.ownsRod()&&h.getBlockState(P.above()).is(Blocks.LIGHTNING_ROD),"owned physical rod exists before real wrench");actor.setPos(Vec3.atCenterOf(b.getBlockPos().south()));h.assertTrue(com.jdte.common.items.EclipseAlloyWrenchItem.pickupMachine(h.getLevel(),b.getBlockPos(),actor)&&h.getBlockState(P.above()).isAir(),"wrench cleanup occurs before BE removal");var packed=java.util.stream.IntStream.range(0,actor.getInventory().getContainerSize()).mapToObj(actor.getInventory()::getItem).filter(v->v.is(JDTEItems.CHARGED_LIGHTNING_ROD.get())).findFirst().orElseThrow();var destination=P.east(2);h.setBlock(destination.below(),Blocks.STONE);actor.setPos(Vec3.atCenterOf(h.absolutePos(destination.south())));actor.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,packed);var context=new net.minecraft.world.item.context.UseOnContext(actor,net.minecraft.world.InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(h.absolutePos(destination.below())),Direction.UP,h.absolutePos(destination.below()),false));h.assertTrue(packed.useOn(context).consumesAction()&&packed.isEmpty(),"survival actual BlockItem consumes exactly one package");var restored=(ChargedLightningRodBE)h.getBlockEntity(destination);h.assertTrue(restored.getEnergyStorage().getEnergyStored()==10000&&restored.getStrikeCooldown()==200&&!restored.isLightningRenderEnabled()&&!restored.isLightningSoundEnabled(),"energy/real work cooldown/controls all retained on relocation");var data=restored.saveWithFullMetadata();data.putInt("chargedLightningRodCooldown",0);restored.load(data);restored.tickServer();h.assertTrue(h.getBlockState(destination.above()).is(Blocks.LIGHTNING_ROD)&&restored.ownsRod()&&restored.getEnergyStorage().getEnergyStored()==0,"source-owned rod restored once at moved location with exactly one paid resumed strike");for(var e:h.getLevel().getEntitiesOfClass(LightningBolt.class,new AABB(restored.getBlockPos()).inflate(1,4,1)))e.discard();h.setBlock(destination,Blocks.AIR);h.succeed();}
 @GameTest(template="mineral_empty") public static void foreignRodSurvivesMachineRemovalAndFarTargetDoesNotLoad(GameTestHelper h){var b=place(h);h.setBlock(P.above(),Blocks.LIGHTNING_ROD);card(b,JDTEItems.THUNDERSTORM_UPGRADE.get(),0);b.getEnergyStorage().setEnergy(10000);b.tickServer();h.assertTrue(!b.ownsRod(),"existing player rod never claimed");clear(h);h.assertTrue(h.getBlockState(P.above()).is(Blocks.LIGHTNING_ROD),"player-owned rod survives machine break");h.setBlock(P.above(),Blocks.AIR);var far=new BlockPos(1000000,100,1000000);var outside=new ChargedLightningRodBE(far,JDTEBlocks.CHARGED_LIGHTNING_ROD.get().defaultBlockState());outside.setLevel(h.getLevel());outside.getEnergyStorage().setEnergy(10000);outside.tickServer();h.assertTrue(!h.getLevel().hasChunkAt(far)&&outside.getEnergyStorage().getEnergyStored()==10000,"unloaded unregistered target neither loads chunks nor spends FE");h.succeed();}

}
